<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{Bar}from'vue-chartjs';import{Chart as ChartJS,BarElement,LinearScale,CategoryScale,Tooltip,Legend}from'chart.js';import{api,errorMessage}from'../lib/api';ChartJS.register(BarElement,LinearScale,CategoryScale,Tooltip,Legend);const data=ref<any>(),error=ref(''),source=ref('');const chart=computed(()=>({labels:data.value?.movementSeries.map((x:any)=>x.date)??[],datasets:[{label:'Inbound',data:data.value?.movementSeries.map((x:any)=>x.inbound),backgroundColor:'#39c89b'},{label:'Outbound',data:data.value?.movementSeries.map((x:any)=>x.outbound),backgroundColor:'#ef6a6a'}]}));onMounted(async()=>{try{const r=await api.get('/analytics');data.value=r.data.data;source.value=r.data.meta.source}catch(e){error.value=errorMessage(e)}})</script>
<template><div class="page-heading"><div><p class="eyebrow">DECISION INTELLIGENCE</p><h1>Analytics</h1><p>Aggregated operational performance for the last 30 days.</p></div><span class="status healthy">{{source.replaceAll('-',' ')}}</span></div><div v-if="error" class="form-error">{{error}}</div><template v-if="data"><div class="kpi-grid"><article class="kpi-card"><p>Stock value</p><h2>{{data.stockValue.toLocaleString()}} EGP</h2></article><article class="kpi-card"><p>Units on hand</p><h2>{{data.unitsOnHand.toLocaleString()}}</h2></article><article class="kpi-card"><p>Reserved units</p><h2>{{data.reservedUnits.toLocaleString()}}</h2></article><article class="kpi-card"><p>30-day order value</p><h2>{{data.orderValue.toLocaleString()}} EGP</h2></article></div><div class="dashboard-grid"><article class="panel chart-panel"><h3>Inventory movement</h3><Bar :data="chart" :options="{responsive:true,maintainAspectRatio:false}"/></article><article class="panel"><h3>Top inventory value</h3><ul class="activity-list"><li v-for="p in data.topProducts" :key="p.id"><span class="activity-mark"/><div><strong>{{p.name}}</strong><small>{{p.quantity}} units · {{p.value.toLocaleString()}} EGP</small></div></li></ul><small class="muted">Generated {{new Date(data.generatedAt).toLocaleString()}}</small></article></div></template></template>
